17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
65	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
66	     */
67	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        validateRequiredOwnerFields(ownerFieldsDto);
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
119	        owner.setTelephone(normalizedTelephone);
120	        owner.setEmail(normalizeEmail(owner.getEmail()));
121	        if (owner.getRegistrationDate() == null) {
122	            owner.setRegistrationDate(LocalDate.now());
123	        }
124	        rejectDuplicateTelephone(normalizedTelephone);
125	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
126	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
127	        }
128	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
129	        this.clinicService.saveOwner(owner);
130	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	        headers.setLocation(UriComponentsBuilder.newInstance()
132	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
133	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
139	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
140	        if (currentOwner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        currentOwner.setAddress(ownerFieldsDto.getAddress());
144	        currentOwner.setCity(ownerFieldsDto.getCity());
145	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
146	        currentOwner.setLastName(ownerFieldsDto.getLastName());
147	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
148	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
149	        this.clinicService.saveOwner(currentOwner);
150	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Transactional
155	    @Override
156	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
157	        Owner owner = this.clinicService.findOwnerById(ownerId);
158	        if (owner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        this.clinicService.deleteOwner(owner);
162	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        HttpHeaders headers = new HttpHeaders();
173	        Pet pet = petMapper.toPet(petFieldsDto);
174	        owner.setId(ownerId);
175	        pet.setOwner(owner);
176	        pet.getType().setName(null);
177	        this.clinicService.savePet(pet);
178	        PetDto petDto = petMapper.toPetDto(pet);
179	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
180	            .buildAndExpand(pet.getId()).toUri());
181	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
187	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
188	        if (currentOwner != null) {
189	            Pet currentPet = this.clinicService.findPetById(petId);
190	            if (currentPet != null) {
191	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
192	                currentPet.setName(petFieldsDto.getName());
193	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
194	                this.clinicService.savePet(currentPet);
195	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
196	            }
197	        }
198	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
204	        HttpHeaders headers = new HttpHeaders();
205	        Visit visit = visitMapper.toVisit(visitFieldsDto);
206	        Pet pet = new Pet();
207	        pet.setId(petId);
208	        visit.setPet(pet);
209	        this.clinicService.saveVisit(visit);
210	        VisitDto visitDto = visitMapper.toVisitDto(visit);
211	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
212	            .buildAndExpand(visit.getId()).toUri());
213	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
214	    }
215	
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
220	        Owner owner = this.clinicService.findOwnerById(ownerId);
221	        if (owner != null) {
222	            Pet pet = owner.getPet(petId);
223	            if (pet != null) {
224	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
225	            }
226	        }
227	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	    }
229	
230	    /**
231	     * Builds the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'} where
232	     * {@code LAST3} is the upper-cased first three letters of the owner's last name and {@code NNNN}
233	     * is a global 4-digit zero-padded sequence equal to one more than the current number of owners.
234	     * For example an owner named "Smithers" created when 10 owners already exist gets {@code 'SMI-0011'}.
235	     *
236	     * @param lastName the owner's last name
237	     * @return the assigned customer code
238	     */
239	    private String nextCustomerCode(String lastName) {
240	        String letters = lastName == null ? "" : lastName;
241	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
242	        int sequence = this.clinicService.findAllOwners().size() + 1;
243	        return String.format("%s-%04d", last3, sequence);
244	    }
245	
246	    /**
247	     * Rejects an owner payload that is missing or blank in any of the required fields
248	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
249	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
250	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
251	     * guard enforces the rule uniformly for every required field.
252	     *
253	     * @param ownerFieldsDto the submitted owner payload
254	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
255	     */
256	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
257	        List<String> invalidFields = new ArrayList<>();
258	        if (isBlank(ownerFieldsDto.getFirstName())) {
259	            invalidFields.add("firstName");
260	        }
261	        if (isBlank(ownerFieldsDto.getLastName())) {
262	            invalidFields.add("lastName");
263	        }
264	        if (isBlank(ownerFieldsDto.getAddress())) {
265	            invalidFields.add("address");
266	        }
267	        if (isBlank(ownerFieldsDto.getCity())) {
268	            invalidFields.add("city");
269	        }
270	        if (isBlank(ownerFieldsDto.getTelephone())) {
271	            invalidFields.add("telephone");
272	        }
273	        if (!invalidFields.isEmpty()) {
274	            throw new InvalidOwnerFieldsException(invalidFields);
275	        }
276	    }
277	
278	    private boolean isBlank(String value) {
279	        return value == null || value.isBlank();
280	    }
281	
282	    /**
283	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
284	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
285	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
286	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
287	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
288	     *
289	     * @param telephone the raw telephone value from the submitted owner payload
290	     * @return the normalized E.164 telephone number
291	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
292	     */
293	    private String normalizeTelephone(String telephone) {
294	        String raw = telephone == null ? "" : telephone.strip();
295	        boolean hasCountryCode = raw.startsWith("+");
296	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
297	        String digits;
298	        if (hasCountryCode) {
299	            digits = cleaned.substring(1);
300	        } else {
301	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
302	            digits = "61" + national;
303	        }
304	        if (!digits.matches("[0-9]{8,15}")) {
305	            throw new InvalidOwnerFieldsException(List.of("telephone"));
306	        }
307	        return "+" + digits;
308	    }
309	
310	    /**
311	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
312	     * returning {@code null} when the value cannot form a valid E.164 number.
313	     *
314	     * @param telephone an existing owner's stored telephone value
315	     * @return the E.164 form, or {@code null} if it cannot be normalized
316	     */
317	    private String toE164OrNull(String telephone) {
318	        try {
319	            return normalizeTelephone(telephone);
320	        } catch (InvalidOwnerFieldsException ex) {
321	            return null;
322	        }
323	    }
324	
325	    /**
326	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
327	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
328	     * accepted value is trimmed and lower-cased before it is stored and returned.
329	     *
330	     * @param email the raw email value from the submitted owner payload, may be {@code null}
331	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
332	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
333	     */
334	    private String normalizeEmail(String email) {
335	        if (email == null) {
336	            return null;
337	        }
338	        String trimmed = email.strip();
339	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
340	            throw new InvalidOwnerFieldsException(List.of("email"));
341	        }
342	        return trimmed.toLowerCase(Locale.ROOT);
343	    }
344	
345	    /**
346	     * Rejects creating an owner whose E.164 telephone is already used by any other owner.
347	     * Existing owners' telephones are converted to E.164 form before comparison so that
348	     * differently-formatted representations of the same number are treated as duplicates.
349	     *
350	     * @param normalizedTelephone the E.164 telephone of the owner being created
351	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same E.164 telephone
352	     */
353	    private void rejectDuplicateTelephone(String normalizedTelephone) {
354	        boolean duplicate = this.clinicService.findAllOwners().stream()
355	            .map(Owner::getTelephone)
356	            .filter(telephone -> telephone != null)
357	            .map(this::toE164OrNull)
358	            .filter(telephone -> telephone != null)
359	            .anyMatch(normalizedTelephone::equals);
360	        if (duplicate) {
361	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
362	        }
363	    }
364	
365	    /**
366	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
367	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
368	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
369	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
370	     *
371	     * @param lastName the last name of the owner being created
372	     * @param address the address of the owner being created
373	     * @throws DuplicateOwnerHouseholdException if another owner shares the same last name and address
374	     */
375	    private void rejectDuplicateHousehold(String lastName, String address) {
376	        String normalizedLastName = normalizeForComparison(lastName);
377	        String normalizedAddress = normalizeForComparison(address);
378	        boolean duplicate = this.clinicService.findAllOwners().stream()
379	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
380	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
381	        if (duplicate) {
382	            throw new DuplicateOwnerHouseholdException(lastName, address);
383	        }
384	    }
385	
386	    /**
387	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
388	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
389	     * result is lower-cased. A {@code null} value normalizes to the empty string.
390	     *
391	     * @param value the value to normalize, may be {@code null}
392	     * @return the normalized value
393	     */
394	    private String normalizeForComparison(String value) {
395	        if (value == null) {
396	            return "";
397	        }
